// Shared types for the RTI question linter and the escalation ladder. Deterministic data
// shapes only; no LLM output lands here untyped.

export type LintSeverity = "block" | "warn" | "info";

export interface LintFinding {
  ruleId: string;
  severity: LintSeverity;
  title: string;
  explanation: string;
  citationId: string;
  suggestedRewrite?: string;
  rewriteAccepted?: boolean;
  /** A model-phrased alternative to suggestedRewrite. Never generated by or used to decide
   *  anything; purely a second wording an operator may pick instead of the deterministic one. */
  aiPhrasedRewrite?: string;
}

export type CaseStatus =
  | "intake"
  | "processing"
  | "needs_input"
  | "emergency"
  | "ready"
  | "filed"
  | "overdue"
  | "rti_ready"
  | "rti_filed"
  | "appeal_ready"
  | "appeal_filed"
  | "second_appeal_ready"
  | "resolved"
  | "failed";

export type DocumentKind = "grievance" | "reminder" | "rti" | "first_appeal" | "second_appeal" | "collective";

export interface Deadline {
  step: string;
  label: string;
  basis: string;
  sourceUrl?: string;
  startsOn: string;
  dueOn: string;
  status: "pending" | "met" | "missed";
}
